import java.util.*;

class Solution {
    public int minAreaRect(int[][] points) {
        if (points == null || points.length < 4) return 0;
        // map x -> list of ys
        Map<Integer, List<Integer>> xToYs = new HashMap<>();
        for (int[] p : points) {
            xToYs.computeIfAbsent(p[0], k -> new ArrayList<>()).add(p[1]);
        }
        List<Integer> xs = new ArrayList<>(xToYs.keySet());
        Collections.sort(xs);
        // sort y lists
        for (int x : xs) {
            List<Integer> ys = xToYs.get(x);
            Collections.sort(ys);
        }
        // map pair(y1,y2) -> last x seen
        Map<Integer, Integer> lastXForPair = new HashMap<>();
        int minArea = Integer.MAX_VALUE;
        for (int x : xs) {
            List<Integer> ys = xToYs.get(x);
            int m = ys.size();
            for (int i = 0; i < m; ++i) {
                for (int j = i + 1; j < m; ++j) {
                    int y1 = ys.get(i);
                    int y2 = ys.get(j);
                    int key = (y1 << 16) | y2;
                    if (lastXForPair.containsKey(key)) {
                        int prevX = lastXForPair.get(key);
                        int area = (x - prevX) * (y2 - y1);
                        if (area < minArea) minArea = area;
                    }
                    lastXForPair.put(key, x);
                }
            }
        }
        return minArea == Integer.MAX_VALUE ? 0 : minArea;
    }
}

